            dist[idx][i][j] = -1;

    front = back = 0;
    int sx = target[idx].x, sy = target[idx].y;
    dist[idx][sx][sy] = 0;
    queue[back][0] = sx;
    queue[back][1] = sy;
    back++;

    while (front < back) {
        int x = queue[front][0];
        int y = queue[front][1];
        front++;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
