int hungarian() {
    int u[MAXG], v[MAXG], p[MAXG], way[MAXG], minv[MAXG];
    int used[MAXG];
    int n = g;
    for (int i = 0; i < n; i++) {
        p[i] = 0;
        v[i] = 0;
        u[i] = 0;
    }
    for (int i = 0; i < n; i++) {
        p[n] = i;
        int j0 = n;
        for (int j = 0; j < n; j++) {
            minv[j] = INT_MAX;
            used[j] = 0;
        }
        do {
            used[j0] = 1;
            int i0 = p[j0], delta = INT_MAX, j1;
            for (int j = 0; j < n; j++) {
                if (!used[j]) {
                    int cur = cost[i0][j] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != n);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != n);
    }
    int ans = -v[n];
    return ans;
}

