int ng;
int dx[] = {0,0,1,-1,0};
int dy[] = {1,-1,0,0,0};

// BFS state: positions of all ghosts encoded
// Each position: row*C+col, max 400 cells
// State: array of ng positions

typedef struct { int pos[MAXG]; int steps; } State;

#define HASH 1000003
int visited[HASH];
int encode(int *pos) {
    int h = 0;
    for(int i=0;i<ng;i++) h = h*401 + pos[i];
    return ((h%HASH)+HASH)%HASH;
}

State queue[2000000];
int qhead, qtail;

int solve() {
    memset(visited, -1, sizeof(visited));
    qhead = qtail = 0;
    State s0;
    for(int i=0;i<ng;i++) s0.pos[i] = sx[i]*C+sy[i];
    s0.steps = 0;
    int goal[MAXG];
    for(int i=0;i<ng;i++) goal[i] = tx[i]*C+ty[i];

    int h0 = encode(s0.pos);
    visited[h0] = 0;
    queue[qtail++] = s0;

    while(qhead < qtail) {
        State cur = queue[qhead++];
        int done = 1;
        for(int i=0;i<ng;i++) if(cur.pos[i]!=goal[i]){done=0;break;}
        if(done) return cur.steps;

        // Try all combinations of moves for ng ghosts (5^ng)
        int moves[MAXG]; memset(moves,0,sizeof(moves));
        int total = 1; for(int i=0;i<ng;i++) total*=5;
        for(int m=0;m<total;m++) {
            int npos[MAXG]; int tmp=m;
            int valid=1;
            for(int i=0;i<ng;i++) {
                int d=tmp%5; tmp/=5;
                int r=cur.pos[i]/C+dx[d], c=cur.pos[i]%C+dy[d];
                if(r<0||r>=R||c<0||c>=C||grid[r][c]=='#'){valid=0;break;}
                npos[i]=r*C+c;
            }
            if(!valid) continue;
            // Check no two same pos
            for(int i=0;i<ng&&valid;i++) for(int j=i+1;j<ng&&valid;j++) if(npos[i]==npos[j]) valid=0;
            // Check no swap
            for(int i=0;i<ng&&valid;i++) for(int j=i+1;j<ng&&valid;j++) if(npos[i]==cur.pos[j]&&npos[j]==cur.pos[i]) valid=0;
            if(!valid) continue;
            int h=encode(npos);
            if(visited[h]==-1){visited[h]=cur.steps+1; State ns; for(int i=0;i<ng;i++) ns.pos[i]=npos[i]; ns.steps=cur.steps+1; queue[qtail++]=ns;}
        }
    }
    return -1;
}

