#define MAXH 16
#define MAXW 16
#define MAXC 256
#define MAXG 3
#define INF 1000000000

typedef struct {
    int x, y;
} Pos;

typedef struct {
    unsigned char p[MAXG]; /* sorted positions of ghosts */
} State;

static int H, W;
static char grid[MAXH][MAXW + 1];

static int cell_id[MAXH][MAXW];
static Pos cells[MAXC];
static int C; /* number of free cells */

static int G; /* number of ghosts */

static int dist_cell[MAXC][MAXC];

/* hash / visited */
static int fact[300];
static int total_states;

static int start_rank, goal_rank;

/* BFS over state space */
static int *dist_state;

/* combinations ranking */
static int comb[260][5]; /* enough for n<=256, k<=3 */

static int min_int(int a, int b) { return a < b ? a : b; }

static void build_combinations(int nmax) {
    int i, j;
    memset(comb, 0, sizeof(comb));
    for (i = 0; i <= nmax; i++) comb[i][0] = 1;
    for (i = 1; i <= nmax; i++) {
        for (j = 1; j <= 4 && j <= i; j++) {
            comb[i][j] = comb[i - 1][j] + comb[i - 1][j - 1];
        }
    }
}

static int rank_state_arr(const unsigned char *a) {
    if (G == 1) return a[0];
    if (G == 2) {
        int x = a[0], y = a[1];
        return comb[y][2] + comb[x][1];
    }
    /* G == 3 */
    {
        int x = a[0], y = a[1], z = a[2];
        return comb[z][3] + comb[y][2] + comb[x][1];
    }
}

static void unrank_state(int r, unsigned char *a) {
    int i, k, x;
    if (G == 1) {
        a[0] = (unsigned char)r;
        return;
    }
    k = G;
    for (i = C - 1; i >= 0; i--) {
        if (comb[i][k] <= r) {
            a[k - 1] = (unsigned char)i;
            r -= comb[i][k];
            k--;
            if (k == 0) break;
        }
    }
}

static int state_equal_arr(const unsigned char *a, const unsigned char *b) {
    int i;
    for (i = 0; i < G; i++) if (a[i] != b[i]) return 0;
    return 1;
}

static int occupied_except(const unsigned char *a, int who, int pos) {
    int i;
    for (i = 0; i < G; i++) {
        if (i != who && a[i] == pos) return 1;
    }
    return 0;
}

static int edge_cross(Pos a1, Pos a2, Pos b1, Pos b2) {
    /* direct swap forbidden */
    return (a1.x == b2.x && a1.y == b2.y && a2.x == b1.x && a2.y == b1.y);
}

static void sort_small(unsigned char *a, int n) {
    int i, j;
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (a[j] < a[i]) {
                unsigned char t = a[i];
                a[i] = a[j];
                a[j] = t;
            }
        }
    }
}

static int valid_transition(const unsigned char *from, const unsigned char *to) {
    int i, j;

    /* distinct end positions guaranteed after sorting + uniqueness check below */
    for (i = 1; i < G; i++) if (to[i] == to[i - 1]) return 0;

    /* no direct swaps */
    for (i = 0; i < G; i++) {
        for (j = i + 1; j < G; j++) {
            if (edge_cross(cells[from[i]], cells[to[i]], cells[from[j]], cells[to[j]]))
                return 0;
        }
    }

    return 1;
}

static int queue_pop(int *q, int *head) {
    return q[(*head)++];
}

static void queue_push(int *q, int *tail, int v) {
    q[(*tail)++] = v;
}

int main(void) {
