            unsigned char cur[MAXG], nxt[MAXG];
            int d = dist_state[cur_rank];

            unrank_state(cur_rank, cur);

            /* Each ghost may stay or move to one adjacent free cell.
               Enumerate choices for up to 3 ghosts. */
            int opts[MAXG][5];
            int cnt[MAXG];

            for (i = 0; i < G; i++) {
                int id = cur[i];
                int x = cells[id].x, y = cells[id].y;
                cnt[i] = 0;
                opts[i][cnt[i]++] = id; /* stay */

                static const int dx[4] = {-1, 1, 0, 0};
                static const int dy[4] = {0, 0, -1, 1};

                for (k = 0; k < 4; k++) {
                    int nx = x + dx[k], ny = y + dy[k];
