                        dist_state[nr] = d + 1;
                        if (nr == goal_rank) {
                            answer = d + 1;
                            goto done_bfs;
                        }
                        queue_push(queue, &tail, nr);
                    }
                }
            } else if (G == 2) {
                int a, b;
                for (a = 0; a < cnt[0]; a++) {
                    for (b = 0; b < cnt[1]; b++) {
                        nxt[0] = (unsigned char)opts[0][a];
                        nxt[1] = (unsigned char)opts[1][b];
                        sort_small(nxt, 2);
                        if (!valid_transition(cur, nxt)) continue;
                        int nr = rank_state_arr(nxt);
                        if (dist_state[nr] == -1) {
                            dist_state[nr] = d + 1;
                            if (nr == goal_rank) {
                                answer = d + 1;
                                goto done_bfs;
                            }
                            queue_push(queue, &tail, nr);
                        }
                    }
                }
            } else {
                int a, b, c;
                for (a = 0; a < cnt[0]; a++) {
                    for (b = 0; b < cnt[1]; b++) {
                        for (c = 0; c < cnt[2]; c++) {
                            unsigned char raw[3];
                            raw[0] = (unsigned char)opts[0][a];
                            raw[1] = (unsigned char)opts[1][b];
                            raw[2] = (unsigned char)opts[2][c];

                            /* distinct destinations */
                            if (raw[0] == raw[1] || raw[0] == raw[2] || raw[1] == raw[2]) continue;

                            /* check swaps using original identity before sorting */
                            {
                                int bad = 0;
                                if (edge_cross(cells[cur[0]], cells[raw[0]], cells[cur[1]], cells[raw[1]])) bad = 1;
                                if (edge_cross(cells[cur[0]], cells[raw[0]], cells[cur[2]], cells[raw[2]])) bad = 1;
                                if (edge_cross(cells[cur[1]], cells[raw[1]], cells[cur[2]], cells[raw[2]])) bad = 1;
                                if (bad) continue;
                            }

                            nxt[0] = raw[0];
                            nxt[1] = raw[1];
                            nxt[2] = raw[2];
                            sort_small(nxt, 3);

                            int nr = rank_state_arr(nxt);
                            if (dist_state[nr] == -1) {
                                dist_state[nr] = d + 1;
                                if (nr == goal_rank) {
                                    answer = d + 1;
                                    goto done_bfs;
                                }
                                queue_push(queue, &tail, nr);
                            }
                        }
                    }
                }
            }
        }

done_bfs:
        printf("%d\n", answer);

        free(queue);
        free(dist_state);
    }

    return 0;
