struct State {
    vector<int> p; // sorted positions of all ghosts
    bool operator==(const State& other) const { return p == other.p; }
};

struct StateHash {
    size_t operator()(State const& s) const {
        size_t h = 0;
        for (int x : s.p) h = h * 1000003ULL + x + 1;
        return h;
    }
};

