            break

        grid = []
        for _ in range(h):
            grid.append(list(data[i].rstrip("\n")))
            i += 1

        starts = []
        goals = []
        walkable = []

        for r in range(h):
            for c in range(w):
                ch = grid[r][c]
                if ch != '#':
                    walkable.append((r, c))
                if ch == 'a':
                    starts.append((r, c))
                    grid[r][c] = '.'
                elif ch == 'A':
                    goals.append((r, c))
                    grid[r][c] = '.'

        # If there are no ghosts, answer is 0.
        if not starts:
            out.append("0")
            continue

        # Map walkable cells to compact ids.
        cell_id = {}
        for idx, pos in enumerate(walkable):
            cell_id[pos] = idx

        n_cells = len(walkable)
        k = len(starts)

        start_ids = tuple(sorted(cell_id[p] for p in starts))
        goal_ids = tuple(sorted(cell_id[p] for p in goals))

        # Precompute neighbors including "stay".
        neighbors = [[] for _ in range(n_cells)]
        dirs = [(0,0), (1,0), (-1,0), (0,1), (0,-1)]
        for idx, (r, c) in enumerate(walkable):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cell_id:
                    neighbors[idx].append(cell_id[(nr, nc)])

        # Generate next states by choosing a move for each ghost simultaneously.
        def next_states(state):
            occupied = set(state)
            chosen = [0] * k
            result = []

            def dfs(pos_idx, used_targets):
                if pos_idx == k:
                    result.append(tuple(sorted(chosen)))
                    return

                cur = state[pos_idx]
                for nxt in neighbors[cur]:
                    if nxt in used_targets:
                        continue
                    # No direct swap: if some previous ghost moved from nxt to cur, forbid.
                    bad = False
                    for j in range(pos_idx):
                        if state[j] == nxt and chosen[j] == cur:
                            bad = True
                            break
                    if bad:
                        continue
                    chosen[pos_idx] = nxt
                    used_targets.add(nxt)
                    dfs(pos_idx + 1, used_targets)
                    used_targets.remove(nxt)

            dfs(0, set())
            return result

        # BFS over unordered ghost configurations.
        q = deque([start_ids])
        dist = {start_ids: 0}

        ans = -1
        while q:
            state = q.popleft()
            if state == goal_ids:
                ans = dist[state]
                break
            nd = dist[state] + 1
            for ns in next_states(state):
                if ns not in dist:
                    dist[ns] = nd
                    q.append(ns)

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

