                    }
                }
            }
            // Precompute neighbor lists
            List<List<Integer>> adj = new ArrayList<>();
            for (int i = 0; i < cellId; i++) adj.add(new ArrayList<>());
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == '#') continue;
                    int u = id[i][j];
                    for (int d = 0; d < 5; d++) {
                        int ni = i + dr[d];
                        int nj = j + dc[d];
                        if (ni >= 0 && ni < H && nj >= 0 && nj < W && grid[ni][nj] != '#') {
                            adj.get(u).add(id[ni][nj]);
                        }
                    }
                }
            }
            // Encode start and goal states
            int startState = encode(startR, startC);
            int goalState = encode(goalR, goalC);
            // BFS
            Map<Integer, Integer> dist = new HashMap<>();
            Queue<Integer> q = new LinkedList<>();
            dist.put(startState, 0);
            q.add(startState);
            int ans = -1;
