                if (state == goalState) {
                    ans = d;
                    break;
                }
                int[] posR = new int[ghostCount];
                int[] posC = new int[ghostCount];
                decode(state, posR, posC);
                // Generate moves for each ghost
                List<List<Integer>> moves = new ArrayList<>();
                for (int i = 0; i < ghostCount; i++) {
                    List<Integer> possible = new ArrayList<>();
                    int r = posR[i], c = posC[i];
                    int u = id[r][c];
                    for (int v : adj.get(u)) {
                        possible.add(v);
                    }
                    moves.add(possible);
                }
                // Combine moves
                List<int[]> combined = new ArrayList<>();
                combineMoves(moves, 0, new int[ghostCount], combined);
                for (int[] nextIds : combined) {
                    // Check collisions
                    boolean ok = true;
                    for (int i = 0; i < ghostCount; i++) {
                        for (int j = i+1; j < ghostCount; j++) {
                            if (nextIds[i] == nextIds[j]) { ok = false; break; }
                        }
                        if (!ok) break;
                    }
                    if (!ok) continue;
                    // Check swapping
                    for (int i = 0; i < ghostCount; i++) {
                        for (int j = i+1; j < ghostCount; j++) {
                            int u = id[posR[i]][posC[i]];
                            int v = id[posR[j]][posC[j]];
                            if (nextIds[i] == v && nextIds[j] == u) { ok = false; break; }
                        }
                        if (!ok) break;
                    }
                    if (!ok) continue;
                    // Build new state
                    int[] nr = new int[ghostCount];
                    int[] nc = new int[ghostCount];
                    for (int i = 0; i < ghostCount; i++) {
                        int cell = nextIds[i];
                        nr[i] = cell / W;
                        nc[i] = cell % W;
                    }
                    int newState = encode(nr, nc);
                    if (!dist.containsKey(newState)) {
                        dist.put(newState, d+1);
                        q.add(newState);
                    }
                }
            }
            System.out.println(ans);
        }
        sc.close();
    }

    static int encode(int[] r, int[] c) {
        int state = 0;
        for (int i = 0; i < ghostCount; i++) {
            state = state * (H*W) + (r[i]*W + c[i]);
        }
        return state;
    }

    static void decode(int state, int[] r, int[] c) {
        for (int i = ghostCount-1; i >= 0; i--) {
            int cell = state % (H*W);
            state /= (H*W);
            r[i] = cell / W;
            c[i] = cell % W;
        }
    }

    static void combineMoves(List<List<Integer>> moves, int idx, int[] current, List<int[]> result) {
        if (idx == ghostCount) {
            result.add(current.clone());
            return;
        }
        for (int v : moves.get(idx)) {
            current[idx] = v;
            combineMoves(moves, idx+1, current, result);
        }
    }
