/*
Ghosts in a haunted house:
Find the minimum number of synchronous steps to move all ghosts from their current
positions back to designated positions on a grid with walls.

Rules per step:
- Any subset of ghosts may move simultaneously.
- A ghost may move to one of 4 neighboring free cells, or stay.
- Two ghosts may not end in the same cell.
- Two ghosts may not swap positions across one edge in the same step.

This is solved with BFS on states:
state = sorted tuple of occupied corridor-cell indices by ghosts (ghosts are indistinguishable).
A transition between states is valid if there exists a matching from current occupied cells
to next occupied cells such that each chosen move is legal (stay or one-step move), and
the no-swap rule holds pairwise.

Input format used by the classic problem:
Multiple datasets.
Each dataset starts with two integers w h (width, height), terminated by 0 0.
Then h lines of length w describing the map.
Characters:
  '#' wall
  ' ' empty corridor
  'a'..'z' current ghost positions
  'A'..'Z' corresponding target positions
A lowercase and uppercase of same letter belong together, but because ghosts are
indistinguishable for collision constraints and movement cost, the target set is just
the set of uppercase cells and start set is the set of lowercase cells.
The number of lowercase letters equals the number of uppercase letters.

Output:
For each dataset, print the minimum number of steps.
*/
public class Main {
    static int W, H;
    static char[][] grid;

    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    static int cellCount;
    static int[][] id;          // grid -> corridor id, -1 for wall
    static int[] rr, cc;        // corridor id -> row/col
    static long[] codePow;      // not used for hashing, kept if needed

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = read();
            if (c == -1) return null;
            while (c == '\r' || c == '\n') {
                c = read();
                if (c == -1) return "";
            }
            while (c != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
                c = read();
            }
            if (c == '\r') {
                int d = read();
                if (d != '\n' && d != -1) ptr--;
            }
            return sb.toString();
        }
    }

    static class State {
        int[] pos; // sorted corridor ids

        State(int[] p) {
            pos = p;
        }
    }

    static long encode(int[] a) {
        // cellCount <= grid cells, practically small. Use mixed radix.
        long res = 0;
        long base = cellCount + 1L;
        for (int x : a) res = res * base + (x + 1L);
        return res;
    }

    static boolean isAdjacentOrStay(int from, int to) {
        if (from == to) return true;
        int r1 = rr[from], c1 = cc[from];
        int r2 = rr[to], c2 = cc[to];
        return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
    }

    static boolean edgeSwap(int aFrom, int aTo, int bFrom, int bTo) {
        return aFrom == bTo && bFrom == aTo && aFrom != aTo;
    }

    static boolean canTransition(int[] cur, int[] nxt) {
        int n = cur.length;

        // Build bipartite graph: current ghost i can go to next occupied cell j
        // if that move is legal by distance 0/1.
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (isAdjacentOrStay(cur[i], nxt[j])) g[i].add(j);
            }
            if (g[i].isEmpty()) return false;
        }

        // Backtracking matching with no-swap pairwise constraint.
        int[] matchToCur = new int[n];
        Arrays.fill(matchToCur, -1);
        int[] assign = new int[n];
        Arrays.fill(assign, -1);

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> g[i].size()));

        return dfsMatch(0, order, g, cur, nxt, assign, matchToCur);
    }

    static boolean dfsMatch(int idx, Integer[] order, List<Integer>[] g, int[] cur, int[] nxt,
                            int[] assign, int[] matchToCur) {
        int n = order.length;
        if (idx == n) return true;
        int i = order[idx];

        for (int j : g[i]) {
            if (matchToCur[j] != -1) continue;

            boolean ok = true;
            for (int t = 0; t < idx; t++) {
                int ii = order[t];
                int jj = assign[ii];
                if (edgeSwap(cur[i], nxt[j], cur[ii], nxt[jj])) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;

            assign[i] = j;
            matchToCur[j] = i;
            if (dfsMatch(idx + 1, order, g, cur, nxt, assign, matchToCur)) return true;
            matchToCur[j] = -1;
            assign[i] = -1;
        }
        return false;
    }

    static List<int[]> generateCandidateNextStates(int[] cur, int[][] moves) {
        int n = cur.length;
        ArrayList<int[]> res = new ArrayList<>();
        int[] chosen = new int[n];
        boolean[] used = new boolean[cellCount];

        genRec(0, cur, moves, chosen, used, res);
        return res;
    }

    static void genRec(int idx, int[] cur, int[][] moves, int[] chosen, boolean[] used, List<int[]> res) {
        int n = cur.length;
        if (idx == n) {
            int[] nxt = chosen.clone();
            Arrays.sort(nxt);
            // deduplicate due to indistinguishable ghosts / different generation orders
            if (res.isEmpty() || !Arrays.equals(res.get(res.size() - 1), nxt)) {
                // cannot rely on adjacency ordering for dedup here
            }
            res.add(nxt);
            return;
        }

        // To reduce duplicates, process ghosts in fixed order and allow chosen cells distinct.
        for (int to : moves[cur[idx]]) {
            if (used[to]) continue;

            // partial no-swap pruning against already chosen ghosts
            boolean ok = true;
            for (int k = 0; k < idx; k++) {
                if (cur[idx] == chosen[k] && cur[k] == to && cur[idx] != to) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;

            used[to] = true;
            chosen[idx] = to;
            genRec(idx + 1, cur, moves, chosen, used, res);
            used[to] = false;
        }
    }

    static int solve(int[] start, int[] goal, int[][] moves) {
        Arrays.sort(start);
        Arrays.sort(goal);
        long goalCode = encode(goal);

        Queue<State> q = new ArrayDeque<>();
        HashMap<Long, Integer> dist = new HashMap<>();

        long startCode = encode(start);
        q.add(new State(start));
        dist.put(startCode, 0);

        while (!q.isEmpty()) {
            State s = q.poll();
            int d = dist.get(encode(s.pos));
            long sc = encode(s.pos);
            if (sc == goalCode) return d;

            List<int[]> cands = generateCandidateNextStates(s.pos, moves);

            // deduplicate candidates generated from distinguishable ordering
            HashSet<Long> seenLocal = new HashSet<>();
            for (int[] nxt : cands) {
                long code = encode(nxt);
                if (!seenLocal.add(code)) continue;

                if (!canTransition(s.pos, nxt)) continue;

                if (!dist.containsKey(code)) {
                    dist.put(code, d + 1);
                    q.add(new State(nxt));
                }
            }
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String sw = fs.next();
            if (sw == null) break;
            String sh = fs.next();
            if (sh == null) break;

            W = Integer.parseInt(sw);
            H = Integer.parseInt(sh);
            if (W == 0 && H == 0) break;

            grid = new char[H][W];
            for (int i = 0; i < H; i++) {
                String line = fs.nextLine();
                while (line.length() < W) line += " ";
                grid[i] = line.toCharArray();
            }

            id = new int[H][W];
            for (int i = 0; i < H; i++) Arrays.fill(id[i], -1);

            ArrayList<int[]> corridor = new ArrayList<>();
            ArrayList<Integer> startList = new ArrayList<>();
            ArrayList<Integer> goalList = new ArrayList<>();

            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    char ch = grid[r][c];
                    if (ch != '#') {
                        id[r][c] = corridor.size();
                        corridor.add(new int[]{r, c});
                    }
                }
            }

            cellCount = corridor.size();
            rr = new int[cellCount];
            cc = new int[cellCount];
            for (int i = 0; i < cellCount; i++) {
                rr[i] = corridor.get(i)[0];
                cc[i] = corridor.get(i)[1];
            }

            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    char ch = grid[r][c];
                    if (ch >= 'a' && ch <= 'z') startList.add(id[r][c]);
                    if (ch >= 'A' && ch <= 'Z') goalList.add(id[r][c]);
                }
            }

            int n = startList.size();
            int[] start = new int[n];
            int[] goal = new int[n];
            for (int i = 0; i < n; i++) start[i] = startList.get(i);
            for (int i = 0; i < n; i++) goal[i] = goalList.get(i);

            int[][] moves = new int[cellCount][];
            for (int v = 0; v < cellCount; v++) {
                ArrayList<Integer> mv = new ArrayList<>();
                mv.add(v); // stay
                int r = rr[v], c = cc[v];
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (0 <= nr && nr < H && 0 <= nc && nc < W && id[nr][nc] != -1) {
                        mv.add(id[nr][nc]);
                    }
                }
                moves[v] = new int[mv.size()];
                for (int i = 0; i < mv.size(); i++) moves[v][i] = mv.get(i);
            }

            int ans = solve(start, goal, moves);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
